/* Scheduled HR summaries. Preview never sends mail; configuration is admin-only. */
let remindersOwner='',remindersRequest=0,remindersData=null,remindersDraft=null,remindersPreview=null,remindersDirty=false;
const remindersCanAccess=()=>['admin','hr'].includes(auth?.user?.role);
const remindersIsCurrent=(owner,request)=>owner===auth?.user?.id&&owner===remindersOwner&&request===remindersRequest&&tab==='promemoria'&&remindersCanAccess();
function remindersReset(){remindersOwner=auth?.user?.id||'';remindersRequest++;remindersData=null;remindersDraft=null;remindersPreview=null;remindersDirty=false}
function remindersSafeLeave(){return !remindersDirty||confirm('Ci sono modifiche ai promemoria non salvate. Uscire dalla pagina? Restano disponibili in questa sessione.')}
window.addEventListener('beforeunload',e=>{if(remindersDirty&&remindersOwner===auth?.user?.id){e.preventDefault();e.returnValue=''}});
const reminderStatuses={pending:'Da elaborare',sending:'Invio in corso',sent:'Accettato dal server SMTP',accepted:'Accettato dal server SMTP',failed:'Errore · nessun reinvio automatico',uncertain:'Esito incerto · verificare il servizio di posta',simulated:'Simulato · nessuna email inviata'};
const reminderDate=value=>value?new Date(value).toLocaleString('it-IT'):'—';
async function renderReminders(){
 if(!remindersCanAccess())throw Error('Promemoria riservati a HR centrale e amministratori.');
 if(remindersOwner!==auth.user.id)remindersReset();
 const owner=remindersOwner,request=++remindersRequest;
 $('#content').innerHTML='<section class="panel" role="status">Caricamento dei promemoria…</section>';
 try{const data=await api('reminders');if(!remindersIsCurrent(owner,request))return;remindersData=data;if(!remindersDraft||!remindersDirty)remindersDraft=JSON.parse(JSON.stringify(data.config));remindersDraw()}
 catch(error){if(remindersIsCurrent(owner,request))$('#content').innerHTML='<section class="panel error" role="alert">'+esc(error.message)+'</section>'}
}
function remindersPayload(){
 const d=remindersDraft;return {version:d.version,enabled:d.enabled,centers:[...d.centers],topics:[...d.topics],offsets:String(d.offsets).split(',').map(s=>s.trim()).filter(Boolean).map(Number),recipient_mode:d.recipient_mode,central_hr_email:d.central_hr_email,hour:Number(d.hour),max_daily_messages:Number(d.max_daily_messages),max_overdue_days:Number(d.max_overdue_days)};
}
function remindersDraw(){
 const d=remindersDraft,v=remindersData,can=v.can_configure,simulation=Boolean(v.simulation||v.demo_simulated),disabled=can?'':'disabled';
 const checks=(rows,selected,key)=>rows.map(r=>`<label><input type="checkbox" data-reminder-check="${key}" value="${esc(r.id)}" ${selected.includes(r.id)?'checked':''} ${disabled}> ${esc(r.label||r.name)}</label>`).join('');
 $('#content').innerHTML=`<div class="reminder-page"><section class="panel reminder-intro"><span class="eyebrow">SCADENZE E ATTIVITÀ HR</span><h2>Promemoria automatici</h2><p>Riepiloghi per struttura su contratti, documenti, qualifiche, onboarding e presenze da verificare. Le email contengono conteggi; i dettagli delle persone si consultano nel portale.</p><p class="note">${simulation?'<b>Demo: ogni invio è simulato.</b> Nessun messaggio raggiunge destinatari reali.':v.config.enabled?'<b>Programmazione attiva.</b> Il server controlla periodicamente le attività dopo l’ora scelta.':'<b>Programmazione disattivata.</b> Prima di attivarla, l’amministratore configura la posta e verifica i destinatari.'}</p>${!v.smtp_ready?'<p class="note">Il servizio SMTP non è pronto: configurarlo nella pagina Comunicazioni per consentire gli invii.</p>':''}${v.changed_routes?.length?'<p class="error">Sono cambiati i recapiti di '+Number(v.changed_routes.length)+' strutture: i relativi invii sono sospesi. Generare una nuova anteprima e salvare la configurazione dopo la verifica.</p>':''}${v.warnings?.length?'<ul class="reminder-warnings">'+v.warnings.map(w=>'<li>'+esc(w.message)+'</li>').join('')+'</ul>':''}<p class="muted">Fuso orario: Europe/Rome. HR centrale consulta configurazione, anteprime ed esiti; solo l’amministratore può modificare la programmazione.</p></section><section class="panel"><h2>Programmazione e destinatari</h2><form id="reminderForm"><fieldset class="reminder-fields" ${disabled}><label class="reminder-check"><input type="checkbox" id="reminderEnabled" ${d.enabled?'checked':''}> Abilita i promemoria automatici</label><fieldset><legend>Strutture incluse</legend><p class="muted smalltext">Nessuna selezione comprende tutte le strutture attuali. I nuovi recapiti richiedono una nuova conferma.</p><div class="reminder-checks">${checks(v.centers,d.centers,'centers')}</div></fieldset><fieldset><legend>Argomenti</legend><div class="reminder-checks">${checks(v.topics,d.topics,'topics')}</div></fieldset><div class="reminder-grid"><label>Anticipi in giorni<input id="reminderOffsets" required value="${esc(String(d.offsets))}" placeholder="30,15,7,0"><small>Da 1 a 8 valori fra 0 e 365, separati da virgola. 0 include il giorno della scadenza e gli arretrati entro il limite.</small></label><label>Arretrati: massimo giorni<input type="number" id="reminderOverdue" min="1" max="90" required value="${Number(d.max_overdue_days)}"><small>Onboarding e presenze precedenti sono segnalati solo quando in scadenza o arretrati.</small></label><label>Destinazione<select id="reminderMode"><option value="structure_hr" ${d.recipient_mode==='structure_hr'?'selected':''}>Referente HR di ciascuna struttura</option><option value="central_hr" ${d.recipient_mode==='central_hr'?'selected':''}>Solo ufficio HR centrale</option><option value="both" ${d.recipient_mode==='both'?'selected':''}>Struttura e ufficio HR centrale</option></select></label><label>Email dell’ufficio HR centrale<input type="email" id="reminderCentral" maxlength="254" value="${esc(d.central_hr_email)}" placeholder="hr@azienda.it"><small>Necessaria per destinazione centrale o entrambe; nessun uso delle email personali dei dipendenti.</small></label><label>Ora locale di avvio<input type="number" id="reminderHour" min="0" max="23" required value="${Number(d.hour)}"><small>Controllo periodico da questa ora in poi, senza garantire un minuto preciso.</small></label><label>Massimo messaggi al giorno<input type="number" id="reminderLimit" min="1" max="200" required value="${Number(d.max_daily_messages)}"><small>Si applicano anche il limite orario e la dimensione dei lotti SMTP.</small></label></div></fieldset><div class="actions"><button class="btn" type="button" id="reminderPreview">Genera anteprima · nessun invio</button>${can?'<button type="submit" class="btn primary" id="reminderSave">Salva programmazione</button>':''}<button type="button" class="btn" id="reminderReload">Aggiorna esiti</button></div><p id="reminderState" class="muted" aria-live="polite">${remindersDirty?'Modifiche da salvare':'Versione salvata '+Number(d.version)}</p><div id="reminderError" role="alert"></div><div id="reminderPreviewResult" aria-live="polite"></div></form></section><section class="panel" id="reminderHistory"><h2>Storico dei promemoria</h2><p class="muted">Accettato SMTP non conferma la consegna o la lettura. Eventi già elaborati, errori ed esiti incerti non vengono reinviati automaticamente né tramite le campagne manuali. Per un esito incerto controlla il registro del servizio di posta.</p>${v.history.length?'<div class="table-wrap"><table><thead><tr><th>Data</th><th>Destinatario e struttura</th><th>Eventi</th><th>Esito</th><th>Messaggio</th></tr></thead><tbody>'+v.history.map(h=>`<tr><td>${esc(reminderDate(h.created_at))}</td><td>${esc(h.name)}<br>${esc(h.email)}</td><td>${Number(h.event_count)}</td><td>${esc(reminderStatuses[h.status]||h.status)}${h.error?'<p>'+esc(h.error)+'</p>':''}</td><td><details><summary>Leggi riepilogo</summary><b>${esc(h.subject)}</b><pre>${esc(h.body)}</pre></details></td></tr>`).join('')+'</tbody></table></div>':'<p>Nessun promemoria elaborato.</p>'}</section></div>`;
 const invalidate=()=>{remindersDirty=true;remindersPreview=null;$('#reminderState').textContent='Modifiche da salvare';$('#reminderPreviewResult').innerHTML='<p class="note">Configurazione modificata: genera una nuova anteprima prima di abilitare.</p>'};
 if(can){$('#reminderEnabled').onchange=e=>{d.enabled=e.target.checked;invalidate()};for(const [id,key] of [['reminderOffsets','offsets'],['reminderOverdue','max_overdue_days'],['reminderMode','recipient_mode'],['reminderCentral','central_hr_email'],['reminderHour','hour'],['reminderLimit','max_daily_messages']])$('#'+id).oninput=e=>{d[key]=e.target.value;invalidate()};document.querySelectorAll('[data-reminder-check]').forEach(el=>el.onchange=()=>{const key=el.dataset.reminderCheck;d[key]=Array.from(document.querySelectorAll('[data-reminder-check="'+key+'"]:checked')).map(e=>e.value);invalidate()})}
 $('#reminderPreview').onclick=remindersLoadPreview;$('#reminderForm').onsubmit=e=>{e.preventDefault();if(can)remindersSave()};$('#reminderReload').onclick=()=>renderReminders();if(remindersPreview)remindersDrawPreview();
}
async function remindersLoadPreview(){
 const owner=remindersOwner,request=remindersRequest,form=$('#reminderForm');if(!form.reportValidity())return;
 const payload=remindersPayload(),key=JSON.stringify(payload),button=$('#reminderPreview');button.disabled=true;$('#reminderError').textContent='';
 try{const data=await api('reminder_preview',payload);if(!remindersIsCurrent(owner,request)||key!==JSON.stringify(remindersPayload()))return;remindersPreview={...data,payload};remindersDrawPreview()}
 catch(error){if(remindersIsCurrent(owner,request))$('#reminderError').textContent=error.message}finally{if(button.isConnected)button.disabled=false}
}
function remindersDrawPreview(){
 const p=remindersPreview,centers=remindersData.centers;$('#reminderPreviewResult').innerHTML=`<div class="reminder-preview"><h3>Anteprima del ${esc(p.date)}</h3><p><b>${Number(p.total_messages)}</b> riepiloghi pronti · <b>${Number(p.pending_events)}</b> eventi nuovi su ${Number(p.total_events)} rilevati. L’anteprima non invia email; gli eventi possono cambiare prima del controllo programmato.</p><h4>Recapiti da autorizzare</h4><ul>${Object.entries(p.routes).map(([cid,emails])=>'<li><b>'+esc(centers.find(c=>c.id===cid)?.name||cid)+'</b>: '+(emails.length?emails.map(esc).join(', '):'recapito mancante')+'</li>').join('')}</ul>${p.warnings.length?'<ul class="reminder-warnings">'+p.warnings.map(w=>'<li>'+esc(w.message)+'</li>').join('')+'</ul>':''}<details><summary>Leggi i messaggi previsti (${Number(p.messages.length)})</summary>${p.messages.length?p.messages.map(m=>'<article><p><b>A:</b> '+esc(m.email)+'<br><b>Oggetto:</b> '+esc(m.subject)+'</p><pre>'+esc(m.body)+'</pre></article>').join(''):'<p>Non ci sono nuovi eventi da inviare. I recapiti sopra elencati valgono per i prossimi eventi.</p>'}</details>${p.total_messages>p.messages.length?'<p class="note">Anteprima dei primi '+p.messages.length+' messaggi; il totale comprende tutti i destinatari.</p>':''}${remindersData.can_configure&&p.config.enabled?`<label class="reminder-check reminder-confirm"><input type="checkbox" id="reminderConfirm" ${p.can_enable?'':'disabled'}> Ho verificato tutti i recapiti sopra elencati e autorizzo gli invii programmati con questa configurazione.</label>`:''}</div>`;
}
async function remindersSave(){
 const owner=remindersOwner,request=remindersRequest,form=$('#reminderForm');if(!form.reportValidity())return;const payload=remindersPayload();$('#reminderError').textContent='';
 if(payload.enabled&&(!remindersPreview||JSON.stringify(remindersPreview.payload)!==JSON.stringify(payload)||!$('#reminderConfirm')?.checked)){$('#reminderError').textContent='Genera l’anteprima e conferma i recapiti prima di abilitare la programmazione.';return}
 form.inert=true;
 try{const data=await api('reminder_config_save',{...payload,...(payload.enabled?{fingerprint:remindersPreview.fingerprint,confirmed:true}:{})});if(!remindersIsCurrent(owner,request))return;remindersData=data;remindersDraft=JSON.parse(JSON.stringify(data.config));remindersDirty=false;remindersPreview=null;remindersDraw();toast(payload.enabled?'Programmazione salvata. Gli invii seguiranno i controlli previsti.':'Promemoria disattivati.')}
 catch(error){if(remindersIsCurrent(owner,request))$('#reminderError').textContent=error.message}finally{form.inert=false}
}
